function validate(input) {
  const [{ Purchases = [], Params = [] }] = input;
  if (Params.length !== 1) return 'Params must have exactly one row.';
  const [startDate, endDate, minAmount] = Params[0];
  if (startDate === null || endDate === null || minAmount === null) return 'Params needs startDate, endDate and minAmount.';
  if (!/ 00:00:00$/.test(startDate) || !/ 00:00:00$/.test(endDate)) return 'startDate and endDate must be at 00:00:00.';
  if (startDate > endDate) return 'startDate must not be after endDate.';
  const seen = new Set();
  for (const [user, time, amount] of Purchases) {
    if (user === null || time === null || amount === null) return 'Purchases rows need a user_id, a time_stamp and an amount.';
    const key = `${user}|${time}`;
    if (seen.has(key)) return `User ${user} has two purchases at ${time}.`;
    seen.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const day = offset => new Date(Date.UTC(2022, 2, 1 + offset)).toISOString().slice(0, 10);
  const two = n => String(n).padStart(2, '0');
  const clock = () => (rand() < 0.3 ? '00:00:00' : `${two(Math.floor(rand() * 24))}:${two(Math.floor(rand() * 60))}:${two(Math.floor(rand() * 60))}`);
  const small = size === 'small';
  const start = Math.floor(rand() * (small ? 6 : 200));
  const end = start + Math.floor(rand() * (small ? 4 : 120));
  const minAmount = small ? pick([500, 1000, 1000]) : 100 + Math.floor(rand() * 900);
  const Params = [[`${day(start)} 00:00:00`, `${day(end)} 00:00:00`, minAmount]];
  const rows = small ? Math.floor(rand() * 9) : 2000, users = small ? 6 : 500;
  const Purchases = [], seen = new Set();
  for (let tries = 0; Purchases.length < rows && tries < rows * 5; tries++) {
    // Days cluster around the window's edges so boundary instants come up often.
    const offset = small ? pick([start - 1, start, start + 1, end - 1, end, end + 1]) : Math.floor(rand() * 365);
    const time = `${day(Math.max(0, offset))} ${clock()}`;
    const user = 1 + Math.floor(rand() * users);
    if (seen.has(`${user}|${time}`)) continue;
    seen.add(`${user}|${time}`);
    const amount = small ? pick([minAmount - 1, minAmount, minAmount + 1, 300, 4500]) : 1 + Math.floor(rand() * 2000);
    Purchases.push([user, time, amount]);
  }
  return [{ Purchases, Params }];
}
